package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	s := scanner.Text()
	ast := strings.Split(s, " ")
	a, _ := strconv.Atoi(ast[0])
	b, _ := strconv.Atoi(ast[1])
	c, _ := strconv.Atoi(ast[2])
	n, _ := strconv.Atoi(ast[3])

	otv := n - ((a - c) + (b - c) + c)
	if otv > 0 && n > c && a >= c && b >= c {
		fmt.Println(otv)
	} else {
		fmt.Println("-1")
	}
}

